package kr.co.hyeonjang.ai365;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Insets;import android.net.Uri;import android.provider.MediaStore;import android.util.Base64;import android.view.*;import android.webkit.*;import android.widget.*;import java.io.*;import java.util.*;
public class MainActivity extends Activity {
 private WebView web;private ValueCallback<Uri[]> files;private byte[] pendingBytes;private Uri captureUri;
 private GeolocationPermissions.Callback locationCallback;private String locationOrigin;
 private static final int PICK=120, SAVE=121;private static final String HOST="appassets.androidplatform.net";
 @Override public void onCreate(Bundle state){super.onCreate(state);FrameLayout root=new FrameLayout(this);web=new WebView(this);root.addView(web,new FrameLayout.LayoutParams(-1,-1));setContentView(root);
  if(Build.VERSION.SDK_INT>=30)root.setOnApplyWindowInsetsListener((v,insets)->{Insets i=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.ime());v.setPadding(i.left,i.top,i.right,i.bottom);return insets;});
  WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSupportZoom(true);s.setBuiltInZoomControls(true);s.setDisplayZoomControls(false);
  web.addJavascriptInterface(new NativeBridge(),"NativeBridge");
  web.setWebViewClient(new WebViewClient(){
   @Override public void onReceivedHttpError(WebView view,WebResourceRequest request,WebResourceResponse response){String host=request.getUrl().getHost();if("dapi.kakao.com".equals(host)||"t1.daumcdn.net".equals(host)){int status=response.getStatusCode();runOnUiThread(()->web.evaluateJavascript("window.dispatchEvent(new CustomEvent(\'kakao-resource-error\',{detail:{status:"+status+"}}));",null));}}
   @Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){Uri u=r.getUrl();if("https".equals(u.getScheme())&&HOST.equals(u.getHost()))return false;if("https".equals(u.getScheme()))openExternal(u.toString());return true;}
   @Override public WebResourceResponse shouldInterceptRequest(WebView w,WebResourceRequest r){Uri u=r.getUrl();if(!HOST.equals(u.getHost()))return null;String p=u.getPath();if(p==null||p.equals("/"))p="/index.html";if(p.contains("..")||!p.matches("/[A-Za-z0-9_./-]+"))return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));try{String mime=p.endsWith(".mjs")||p.endsWith(".js")?"application/javascript":p.endsWith(".css")?"text/css":p.endsWith(".png")?"image/png":p.endsWith(".svg")?"image/svg+xml":p.endsWith(".json")?"application/json":"text/html";Map<String,String> headers=new HashMap<>();headers.put("X-Content-Type-Options","nosniff");headers.put("Content-Security-Policy","default-src 'self'; script-src 'self' https://dapi.kakao.com https://t1.daumcdn.net https://t1.kakaocdn.net; style-src 'self' 'unsafe-inline'; img-src 'self' blob: data: https://*.daumcdn.net https://*.kakaocdn.net https://*.kakao.com; connect-src 'self' https:; object-src 'none'; child-src 'none'; base-uri 'none'; form-action 'self'");return new WebResourceResponse(mime,"UTF-8",200,"OK",headers,getAssets().open("web"+p));}catch(IOException e){return new WebResourceResponse("text/plain","UTF-8",404,"Not Found",null,new ByteArrayInputStream(new byte[0]));}}
  });
  web.setWebChromeClient(new WebChromeClient(){
   @Override public void onGeolocationPermissionsShowPrompt(String origin,GeolocationPermissions.Callback callback){
    if (!("https://"+HOST).equals(origin)&&!("https://"+HOST+"/").equals(origin)){callback.invoke(origin,false,false);return;}
    if(checkSelfPermission(android.Manifest.permission.ACCESS_COARSE_LOCATION)==android.content.pm.PackageManager.PERMISSION_GRANTED){callback.invoke(origin,true,false);return;}
    if(locationCallback!=null)locationCallback.invoke(locationOrigin,false,false);
    locationOrigin=origin;locationCallback=callback;
    requestPermissions(new String[]{android.Manifest.permission.ACCESS_FINE_LOCATION,android.Manifest.permission.ACCESS_COARSE_LOCATION},122);
   }
   @Override public boolean onShowFileChooser(WebView w,ValueCallback<Uri[]> cb,FileChooserParams params){if(files!=null)files.onReceiveValue(null);files=cb;Intent intent;
    if(params.isCaptureEnabled()&&Build.VERSION.SDK_INT>=29){ContentValues values=new ContentValues();values.put(MediaStore.Images.Media.DISPLAY_NAME,"현장AI365_"+System.currentTimeMillis()+".jpg");values.put(MediaStore.Images.Media.MIME_TYPE,"image/jpeg");captureUri=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,values);intent=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);intent.putExtra(MediaStore.EXTRA_OUTPUT,captureUri);intent.addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_READ_URI_PERMISSION);}
    else{intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.setType(params.getAcceptTypes().length>0&&params.getAcceptTypes()[0].contains("json")?"application/json":"image/*");intent.addCategory(Intent.CATEGORY_OPENABLE);intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,params.getMode()==FileChooserParams.MODE_OPEN_MULTIPLE);}
    try{startActivityForResult(intent,PICK);return true;}catch(ActivityNotFoundException e){cb.onReceiveValue(null);files=null;Toast.makeText(MainActivity.this,"파일 선택 앱을 찾지 못했습니다.",Toast.LENGTH_LONG).show();return true;}
   }
  });
  web.loadUrl("https://"+HOST+"/index.html");
 }
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==122&&locationCallback!=null){boolean granted=checkSelfPermission(android.Manifest.permission.ACCESS_COARSE_LOCATION)==android.content.pm.PackageManager.PERMISSION_GRANTED;locationCallback.invoke(locationOrigin,granted,false);locationCallback=null;locationOrigin=null;}}
 private void openExternal(String url){Uri u=Uri.parse(url);if(!"https".equals(u.getScheme()))return;runOnUiThread(()->{try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(ActivityNotFoundException e){Toast.makeText(this,"연결할 앱이 없습니다.",Toast.LENGTH_SHORT).show();}});}
 private class NativeBridge {
  @JavascriptInterface public String getPublicApiConfig(){try(InputStream in=getAssets().open("_public-api-runtime.json");ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[4096];int count;while((count=in.read(buffer))!=-1)out.write(buffer,0,count);org.json.JSONObject config=new org.json.JSONObject(new String(out.toByteArray(),java.nio.charset.StandardCharsets.UTF_8));org.json.JSONObject safe=new org.json.JSONObject();safe.put("origin",config.optString("origin"));return safe.toString();}catch(Exception e){return "{}";}}

  @JavascriptInterface public String getFirebaseConfig(){try(InputStream in=getAssets().open("_firebase-runtime.json");ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[4096];int count;while((count=in.read(buffer))!=-1)out.write(buffer,0,count);return new String(out.toByteArray(),java.nio.charset.StandardCharsets.UTF_8);}catch(Exception e){return "{}";}}
  @JavascriptInterface public void googleLogin(){runOnUiThread(()->{try{org.json.JSONObject config=new org.json.JSONObject(getFirebaseConfig());String client=config.optString("googleClientId");if(client.isEmpty())throw new IllegalStateException();GoogleLogin.start(MainActivity.this,client,new GoogleLogin.Result(){public void success(String token){web.evaluateJavascript("window.dispatchEvent(new CustomEvent('native-google-result',{detail:{token:"+org.json.JSONObject.quote(token)+"}}));",null);}public void failure(){web.evaluateJavascript("window.dispatchEvent(new CustomEvent('native-google-result',{detail:{error:true}}));",null);}});}catch(Exception e){web.evaluateJavascript("window.dispatchEvent(new CustomEvent('native-google-result',{detail:{error:true}}));",null);}});}
  @JavascriptInterface public void openLink(String url){openExternal(url);}
  @JavascriptInterface public void saveFile(String name,String mime,String base64){if(base64==null||base64.length()>45000000||!(mime.equals("application/pdf")||mime.equals("application/json")||mime.equals("image/jpeg")||mime.equals("image/png")||mime.equals("image/webp"))){runOnUiThread(()->Toast.makeText(MainActivity.this,"이 파일은 PC에서 저장해 주세요.",Toast.LENGTH_LONG).show());return;}runOnUiThread(()->{if(pendingBytes!=null){Toast.makeText(MainActivity.this,"현재 파일 저장을 먼저 마쳐 주세요.",Toast.LENGTH_SHORT).show();return;}try{pendingBytes=Base64.decode(base64,Base64.DEFAULT);Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(mime);i.putExtra(Intent.EXTRA_TITLE,name.replaceAll("[\\\\/:*?\"<>|]","_"));startActivityForResult(i,SAVE);}catch(Exception e){pendingBytes=null;Toast.makeText(MainActivity.this,"파일 저장을 시작하지 못했습니다.",Toast.LENGTH_LONG).show();}});}
 }
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);
  if(request==PICK&&files!=null){Uri[] selected=null;if(result==RESULT_OK){if(captureUri!=null)selected=new Uri[]{captureUri};else if(data!=null&&data.getClipData()!=null){int n=data.getClipData().getItemCount();selected=new Uri[n];for(int i=0;i<n;i++)selected[i]=data.getClipData().getItemAt(i).getUri();}else if(data!=null&&data.getData()!=null)selected=new Uri[]{data.getData()};}else if(captureUri!=null)getContentResolver().delete(captureUri,null,null);files.onReceiveValue(selected);files=null;captureUri=null;}
  if(request==SAVE){if(result==RESULT_OK&&data!=null&&data.getData()!=null&&pendingBytes!=null){try(OutputStream out=getContentResolver().openOutputStream(data.getData(),"w")){out.write(pendingBytes);Toast.makeText(this,"파일을 저장했습니다.",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"파일 저장에 실패했습니다.",Toast.LENGTH_LONG).show();}}if(pendingBytes!=null)Arrays.fill(pendingBytes,(byte)0);pendingBytes=null;}
 }
 @Override public void onBackPressed(){web.evaluateJavascript("(function(){var d=document.getElementById('modal');if(d&&d.open){d.close();return true;}if(location.hash!=='#home'){location.hash='home';return true;}return false;})()",v->{if(!"true".equals(v))super.onBackPressed();});}
 @Override protected void onPause(){web.onPause();super.onPause();}
 @Override protected void onResume(){super.onResume();web.onResume();}
 @Override protected void onDestroy(){if(files!=null)files.onReceiveValue(null);web.removeJavascriptInterface("NativeBridge");web.destroy();super.onDestroy();}
}
